-- Exact technical copy upgrade; old publications and acceptances remain immutable.
-- Runs atomically under the ordinary migration runner. Empty installations use seeds.
-- Unknown edits in a published target field abort before any publication is committed.
CREATE FUNCTION pg_temp.beta_credit_copy_leaf(value jsonb, old_values jsonb, replacement text)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE result jsonb; pair record;
BEGIN
  IF jsonb_typeof(value) = 'string' THEN
    IF old_values ? (value #>> '{}') THEN RETURN to_jsonb(replacement); END IF;
    RETURN value;
  ELSIF jsonb_typeof(value) = 'array' THEN
    SELECT COALESCE(jsonb_agg(pg_temp.beta_credit_copy_leaf(item,old_values,replacement) ORDER BY n),'[]'::jsonb)
      INTO result FROM jsonb_array_elements(value) WITH ORDINALITY a(item,n);
    RETURN result;
  ELSIF jsonb_typeof(value) = 'object' THEN
    SELECT COALESCE(jsonb_object_agg(key,pg_temp.beta_credit_copy_leaf(val,old_values,replacement)),'{}'::jsonb)
      INTO result FROM jsonb_each(value) a(key,val);
    RETURN result;
  END IF;
  RETURN value;
END; $$;

CREATE FUNCTION pg_temp.beta_credit_copy_contains(value jsonb, expected text)
RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN
  IF jsonb_typeof(value)='string' THEN RETURN (value #>> '{}')=expected;
  ELSIF jsonb_typeof(value)='array' THEN
    RETURN EXISTS(SELECT 1 FROM jsonb_array_elements(value) a(item) WHERE pg_temp.beta_credit_copy_contains(item,expected));
  ELSIF jsonb_typeof(value)='object' THEN
    RETURN EXISTS(SELECT 1 FROM jsonb_each(value) a(key,item) WHERE pg_temp.beta_credit_copy_contains(item,expected));
  END IF;
  RETURN false;
END; $$;

CREATE FUNCTION pg_temp.beta_credit_copy_upgrade(value jsonb, group_key text, locale_key text, strict boolean)
RETURNS jsonb LANGUAGE plpgsql AS $function$
DECLARE rule jsonb; found boolean;
BEGIN
  FOR rule IN SELECT item FROM jsonb_array_elements($copy$[{"group":"page:terms","locale":"en","semantic":"credit_allowance","old":["The beta includes three promotional call credits. A credit is reserved when a call starts. It is used only after the recipient consents and gives a substantive answer to your task. A factual negative answer, an answer that they do not know, or a referral to another contact also counts. A connection, greeting, silence or immediate refusal alone does not use a credit. If no substantive answer is confirmed, the credit is returned when the call ends. The task does not have to be resolved. No payments during the beta. Supported destinations, languages, limits, features and availability may change during the beta."],"next":"The current beta credit allowance is shown at registration and in your account. A credit is reserved when a call starts. It is used only after the recipient consents and gives a substantive answer to your task. A factual negative answer, an answer that they do not know, or a referral to another contact also counts. A connection, greeting, silence or immediate refusal alone does not use a credit. If no substantive answer is confirmed, the credit is returned when the call ends. The task does not have to be resolved. No payments during the beta. Supported destinations, languages, limits, features and availability may change during the beta."},{"group":"collection:landing","locale":"en","semantic":"credit_badge","old":["3 call credits"],"next":"Call credits for the beta"},{"group":"collection:landing","locale":"en","semantic":"credit_cta","old":["Start with 3 free call credits. A credit is used only after the recipient agrees and gives a substantive answer about your task."],"next":"See the current call-credit allowance when registering. A credit is used only after the recipient agrees and gives a substantive answer about your task."},{"group":"page:terms","locale":"de","semantic":"credit_allowance","old":["Die Beta umfasst drei Anrufguthaben. Beim Start wird ein Anrufguthaben reserviert. Es wird erst verbraucht, wenn die angerufene Person zugestimmt und inhaltlich auf Ihr Anliegen geantwortet hat. Auch eine sachlich negative Antwort, Nichtwissen oder der Verweis an eine andere Stelle zählt. Eine Verbindung, Begrüssung, Stille oder sofortige Gesprächsverweigerung allein verbraucht kein Guthaben. Wird keine inhaltliche Antwort bestätigt, erhalten Sie das Guthaben nach Anrufende zurück. Das Anliegen muss nicht gelöst sein. Während der Beta gibt es keine Zahlungen. Unterstützte Ziele, Sprachen, Limiten, Funktionen und Verfügbarkeit können sich während der Beta ändern."],"next":"Das aktuelle Beta-Anrufguthaben wird bei der Registrierung und in Ihrem Konto angezeigt. Beim Start wird ein Anrufguthaben reserviert. Es wird erst verbraucht, wenn die angerufene Person zugestimmt und inhaltlich auf Ihr Anliegen geantwortet hat. Auch eine sachlich negative Antwort, Nichtwissen oder der Verweis an eine andere Stelle zählt. Eine Verbindung, Begrüssung, Stille oder sofortige Gesprächsverweigerung allein verbraucht kein Guthaben. Wird keine inhaltliche Antwort bestätigt, erhalten Sie das Guthaben nach Anrufende zurück. Das Anliegen muss nicht gelöst sein. Während der Beta gibt es keine Zahlungen. Unterstützte Ziele, Sprachen, Limiten, Funktionen und Verfügbarkeit können sich während der Beta ändern."},{"group":"collection:landing","locale":"de","semantic":"credit_badge","old":["3 Anrufguthaben"],"next":"Anrufguthaben für die Beta"},{"group":"collection:landing","locale":"de","semantic":"credit_cta","old":["Starten Sie mit 3 kostenlosen Anrufguthaben. Ein Guthaben wird erst nach Zustimmung und einer inhaltlichen Antwort auf Ihr Anliegen verbraucht."],"next":"Das aktuelle Anrufguthaben sehen Sie bei der Registrierung. Ein Guthaben wird erst nach Zustimmung und einer inhaltlichen Antwort auf Ihr Anliegen verbraucht."},{"group":"page:terms","locale":"fr","semantic":"credit_allowance","old":["La bêta comprend trois crédits d'appel offerts. Un crédit est réservé au début de l'appel. Il n'est utilisé que si la personne accepte la conversation et apporte une réponse de fond à votre demande. Une réponse négative factuelle, le fait de ne pas savoir ou une orientation vers un autre contact comptent aussi. Une connexion, une salutation, un silence ou un refus immédiat ne suffisent pas. Si aucune réponse de fond n'est confirmée, le crédit est rendu à la fin de l'appel. Votre demande n'a pas besoin d'être résolue. Aucun paiement pendant la bêta. Les destinations, langues, limites, fonctionnalités et disponibilités peuvent changer pendant la bêta."],"next":"Le quota actuel de crédits bêta est indiqué à l’inscription et dans votre compte. Un crédit est réservé au début de l'appel. Il n'est utilisé que si la personne accepte la conversation et apporte une réponse de fond à votre demande. Une réponse négative factuelle, le fait de ne pas savoir ou une orientation vers un autre contact comptent aussi. Une connexion, une salutation, un silence ou un refus immédiat ne suffisent pas. Si aucune réponse de fond n'est confirmée, le crédit est rendu à la fin de l'appel. Votre demande n'a pas besoin d'être résolue. Aucun paiement pendant la bêta. Les destinations, langues, limites, fonctionnalités et disponibilités peuvent changer pendant la bêta."},{"group":"collection:landing","locale":"fr","semantic":"credit_badge","old":["3 crédits d'appel"],"next":"Crédits d’appel pour la bêta"},{"group":"collection:landing","locale":"fr","semantic":"credit_cta","old":["Commencez avec 3 crédits d'appel gratuits. Un crédit n'est utilisé que si la personne accepte et apporte une réponse de fond à votre demande."],"next":"Consultez le quota actuel de crédits d’appel à l’inscription. Un crédit n'est utilisé que si la personne accepte et apporte une réponse de fond à votre demande."},{"group":"page:terms","locale":"it","semantic":"credit_allowance","old":["La beta include tre crediti chiamata promozionali. Un credito viene riservato all'avvio della chiamata. Viene usato solo quando il destinatario acconsente e dà una risposta sostanziale alla tua richiesta. Contano anche una risposta negativa concreta, un «non lo so» o il rinvio a un altro contatto. Il solo collegamento, un saluto, il silenzio o un rifiuto immediato non consumano credito. Se non viene confermata una risposta sostanziale, il credito viene restituito alla fine della chiamata. Non è necessario che la richiesta sia risolta. Nessun pagamento durante la beta. Destinazioni, lingue, limiti, funzionalità e disponibilità possono cambiare durante la beta."],"next":"La quota attuale di crediti beta è indicata alla registrazione e nel tuo account. Un credito viene riservato all'avvio della chiamata. Viene usato solo quando il destinatario acconsente e dà una risposta sostanziale alla tua richiesta. Contano anche una risposta negativa concreta, un «non lo so» o il rinvio a un altro contatto. Il solo collegamento, un saluto, il silenzio o un rifiuto immediato non consumano credito. Se non viene confermata una risposta sostanziale, il credito viene restituito alla fine della chiamata. Non è necessario che la richiesta sia risolta. Nessun pagamento durante la beta. Destinazioni, lingue, limiti, funzionalità e disponibilità possono cambiare durante la beta."},{"group":"collection:landing","locale":"it","semantic":"credit_badge","old":["3 crediti chiamata"],"next":"Crediti chiamata per la beta"},{"group":"collection:landing","locale":"it","semantic":"credit_cta","old":["Inizia con 3 crediti chiamata gratuiti. Un credito viene usato solo se il destinatario acconsente e dà una risposta sostanziale alla tua richiesta."],"next":"Consulta la quota attuale di crediti chiamata alla registrazione. Un credito viene usato solo se il destinatario acconsente e dà una risposta sostanziale alla tua richiesta."},{"group":"page:terms","locale":"rm","semantic":"credit_allowance","old":["La beta cuntegna trais credits da telefonat gratuits. In credit vegn reservà al cumenzament dal telefonat. El vegn duvrà mo suenter che la persuna ha dà ses consentiment e respundì davart il cuntegn da tia dumonda. Ina resposta negativa concreta, il fatg da betg savair u il rinviament ad in auter contact quintan era. Ina colliaziun, in salid, silenzi u in refus immediat na dovran betg in credit. Sche nagina resposta davart il cuntegn vegn confermada, vegn il credit restituì a la fin dal telefonat. L'incumbensa na sto betg esser schliada. Durant la beta na datti nagins pajaments. Destinaziuns, linguas, cunfins, funcziuns e disponibladad pon sa midar durant la beta."],"next":"La quota actuala da credits beta vegn mussada tar la registraziun ed en tes conto. In credit vegn reservà al cumenzament dal telefonat. El vegn duvrà mo suenter che la persuna ha dà ses consentiment e respundì davart il cuntegn da tia dumonda. Ina resposta negativa concreta, il fatg da betg savair u il rinviament ad in auter contact quintan era. Ina colliaziun, in salid, silenzi u in refus immediat na dovran betg in credit. Sche nagina resposta davart il cuntegn vegn confermada, vegn il credit restituì a la fin dal telefonat. L'incumbensa na sto betg esser schliada. Durant la beta na datti nagins pajaments. Destinaziuns, linguas, cunfins, funcziuns e disponibladad pon sa midar durant la beta."},{"group":"collection:landing","locale":"rm","semantic":"credit_badge","old":["3 credits da telefonat"],"next":"Credits da telefonat per la beta"},{"group":"collection:landing","locale":"rm","semantic":"credit_cta","old":["Cumenza cun 3 credits da telefonat gratuits. In credit vegn duvrà mo sche la persuna è d'accord e respunda davart il ccuntegn da tia dumonda."],"next":"Guarda la quota actuala da credits da telefonat tar la registraziun. In credit vegn duvrà mo sche la persuna è d'accord e respunda davart il ccuntegn da tia dumonda."},{"group":"page:terms","locale":"ru","semantic":"credit_allowance","old":["В бета-версии доступны три бесплатных кредита на звонки. Кредит резервируется в начале звонка. Он расходуется, только если собеседник согласился на разговор и дал содержательный ответ по вашей задаче. Обоснованный отрицательный ответ, «не знаю» или направление к другому контакту тоже учитываются. Одного соединения, приветствия, молчания или немедленного отказа недостаточно. Если содержательный ответ не подтверждён, кредит возвращается после звонка. Задача при этом не обязательно должна быть решена. Во время бета-тестирования платежей нет. Направления, языки, ограничения, функции и доступность могут меняться в ходе бета-тестирования."],"next":"Текущая квота кредитов беты указана при регистрации и в вашем аккаунте. Кредит резервируется в начале звонка. Он расходуется, только если собеседник согласился на разговор и дал содержательный ответ по вашей задаче. Обоснованный отрицательный ответ, «не знаю» или направление к другому контакту тоже учитываются. Одного соединения, приветствия, молчания или немедленного отказа недостаточно. Если содержательный ответ не подтверждён, кредит возвращается после звонка. Задача при этом не обязательно должна быть решена. Во время бета-тестирования платежей нет. Направления, языки, ограничения, функции и доступность могут меняться в ходе бета-тестирования."},{"group":"collection:landing","locale":"ru","semantic":"credit_badge","old":["3 кредита на звонки"],"next":"Кредиты на звонки в бете"},{"group":"collection:landing","locale":"ru","semantic":"credit_cta","old":["Начните с 3 бесплатных кредитов. Кредит расходуется, только если собеседник согласился на разговор и дал содержательный ответ по вашей задаче."],"next":"Текущая квота кредитов на звонки указана при регистрации. Кредит расходуется, только если собеседник согласился на разговор и дал содержательный ответ по вашей задаче."},{"group":"page:terms","locale":"uk","semantic":"credit_allowance","old":["У бета-версії доступні три безкоштовні кредити на дзвінки. Кредит резервується на початку дзвінка. Він витрачається, лише якщо співрозмовник погодився на розмову й дав змістовну відповідь щодо вашого завдання. Обґрунтована негативна відповідь, «не знаю» або скерування до іншого контакту також враховуються. Самого з’єднання, привітання, мовчання чи негайної відмови недостатньо. Якщо змістовну відповідь не підтверджено, кредит повертається після дзвінка. Завдання при цьому не обов’язково має бути вирішене. Під час бета-тестування платежів немає. Напрямки, мови, обмеження, функції й доступність можуть змінюватися під час бета-тестування."],"next":"Поточна квота кредитів бета-тесту вказана під час реєстрації та у вашому акаунті. Кредит резервується на початку дзвінка. Він витрачається, лише якщо співрозмовник погодився на розмову й дав змістовну відповідь щодо вашого завдання. Обґрунтована негативна відповідь, «не знаю» або скерування до іншого контакту також враховуються. Самого з’єднання, привітання, мовчання чи негайної відмови недостатньо. Якщо змістовну відповідь не підтверджено, кредит повертається після дзвінка. Завдання при цьому не обов’язково має бути вирішене. Під час бета-тестування платежів немає. Напрямки, мови, обмеження, функції й доступність можуть змінюватися під час бета-тестування."},{"group":"collection:landing","locale":"uk","semantic":"credit_badge","old":["3 кредити на дзвінки"],"next":"Кредити на дзвінки в бета-тесті"},{"group":"collection:landing","locale":"uk","semantic":"credit_cta","old":["Почніть із 3 безкоштовних кредитів. Кредит витрачається, лише якщо співрозмовник погодився на розмову й дав змістовну відповідь щодо вашого завдання."],"next":"Поточна квота кредитів на дзвінки вказана під час реєстрації. Кредит витрачається, лише якщо співрозмовник погодився на розмову й дав змістовну відповідь щодо вашого завдання."}]$copy$::jsonb) a(item)
    WHERE item->>'group'=group_key AND (locale_key IS NULL OR item->>'locale'=locale_key)
  LOOP
    found := pg_temp.beta_credit_copy_contains(value,rule->>'next') OR EXISTS(
      SELECT 1 FROM jsonb_array_elements_text(rule->'old') a(old) WHERE pg_temp.beta_credit_copy_contains(value,old));
    IF strict AND NOT found THEN
      RAISE EXCEPTION 'BETA_CREDIT_COPY_PREFLIGHT: % locale % field % has an unknown edit; review it before rollout',group_key,rule->>'locale',rule->>'semantic';
    END IF;
    value := pg_temp.beta_credit_copy_leaf(value,rule->'old',rule->>'next');
  END LOOP;
  RETURN value;
END; $function$;

DO $$
DECLARE page record; revision record; localized record; collection record;
  next_id uuid; next_number integer; next_sections jsonb; next_snapshot jsonb; changed boolean;
BEGIN
  LOCK TABLE content_page_revisions, content_page_revision_localizations, content_editorial_revisions IN SHARE ROW EXCLUSIVE MODE;
  FOR page IN SELECT * FROM content_pages WHERE key IN ('terms') LOOP
    SELECT * INTO revision FROM content_page_revisions WHERE page_id=page.id AND status='published' ORDER BY revision_number DESC LIMIT 1;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF (SELECT count(*) FROM content_page_revision_localizations WHERE revision_id=revision.id AND locale IN ('en','de','fr','it','rm','ru','uk')) <> 7 THEN
      RAISE EXCEPTION 'BETA_CREDIT_COPY_PREFLIGHT: page % requires all seven locales',page.key;
    END IF;
    changed := false;
    FOR localized IN SELECT * FROM content_page_revision_localizations WHERE revision_id=revision.id LOOP
      next_sections := pg_temp.beta_credit_copy_upgrade(localized.sections,'page:'||page.key,localized.locale,true);
      changed := changed OR next_sections<>localized.sections;
    END LOOP;
    IF changed THEN
      next_id := gen_random_uuid();
      SELECT max(revision_number)+1 INTO next_number FROM content_page_revisions WHERE page_id=page.id;
      INSERT INTO content_page_revisions(id,page_id,revision_number,status,requires_reacceptance,created_by_user_id,created_at,updated_at,published_at,required_locales)
        VALUES(next_id,page.id,next_number,'published',false,NULL,now(),now(),now(),'["en","de","fr","it","rm","ru","uk"]');
      INSERT INTO content_page_revision_localizations(id,revision_id,locale,title,summary,sections,seo_title,seo_description,source_revision_number,created_at,updated_at)
        SELECT gen_random_uuid(),next_id,locale,title,summary,pg_temp.beta_credit_copy_upgrade(sections,'page:'||page.key,locale,true),seo_title,seo_description,next_number,now(),now()
          FROM content_page_revision_localizations WHERE revision_id=revision.id;
      UPDATE content_pages SET updated_at=now() WHERE id=page.id;
    END IF;
    -- Keep existing drafts and their metadata; update only recognized old leaves.
    UPDATE content_page_revision_localizations l SET sections=pg_temp.beta_credit_copy_upgrade(l.sections,'page:'||page.key,l.locale,false),updated_at=now()
      FROM content_page_revisions r WHERE r.id=l.revision_id AND r.page_id=page.id AND r.status='draft'
        AND l.sections<>pg_temp.beta_credit_copy_upgrade(l.sections,'page:'||page.key,l.locale,false);
  END LOOP;
  FOR collection IN SELECT * FROM content_editorial_collections WHERE key IN ('landing') LOOP
    SELECT * INTO revision FROM content_editorial_revisions WHERE collection_id=collection.id AND status='published' ORDER BY revision_number DESC LIMIT 1;
    IF NOT FOUND THEN CONTINUE; END IF;
    next_snapshot := pg_temp.beta_credit_copy_upgrade(revision.snapshot,'collection:'||collection.key,NULL,true);
    IF next_snapshot<>revision.snapshot THEN
      SELECT max(revision_number)+1 INTO next_number FROM content_editorial_revisions WHERE collection_id=collection.id;
      INSERT INTO content_editorial_revisions(id,collection_id,revision_number,status,snapshot,created_by_user_id,created_at,updated_at,published_at,required_locales)
        VALUES(gen_random_uuid(),collection.id,next_number,'published',next_snapshot,NULL,now(),now(),now(),'["en","de","fr","it","rm","ru","uk"]');
      UPDATE content_editorial_collections SET updated_at=now() WHERE id=collection.id;
    END IF;
    UPDATE content_editorial_revisions SET snapshot=pg_temp.beta_credit_copy_upgrade(snapshot,'collection:'||collection.key,NULL,false),updated_at=now()
      WHERE collection_id=collection.id AND status='draft' AND snapshot<>pg_temp.beta_credit_copy_upgrade(snapshot,'collection:'||collection.key,NULL,false);
  END LOOP;
END; $$;
DROP FUNCTION pg_temp.beta_credit_copy_upgrade(jsonb,text,text,boolean);
DROP FUNCTION pg_temp.beta_credit_copy_contains(jsonb,text);
DROP FUNCTION pg_temp.beta_credit_copy_leaf(jsonb,jsonb,text);
